export const faunaList=Array.from(new Set(diveSites.flatMap(site=>site.animals))).sort();
export const regions=Array.from(new Set(diveSites.map(site=>site.region))).sort();
export const destinationSlugs=Array.from(new Set(diveSites.map(site=>site.destinationSlug)));
export const destinations=destinationSlugs.map(slug=>{
  const sites=diveSites.filter(site=>site.destinationSlug===slug);
  return {slug,name:sites[0].destination,region:sites[0].region,sites:sites.length,animals:Array.from(new Set(sites.flatMap(site=>site.animals))).slice(0,6)};
});
export type Destination = (typeof destinations)[number];